beh('B-form','A1','Client proposal or PreAccept/PreAcceptReply dispatch',['M-phase1','M-attrs','M-send','M-defs'],writes=['Owner batches requests and allocates an instance in its row. startPhase1 computes key-indexed dependencies and installs PREACCEPTED plus fresh bookkeeping.','Follower rejects lower ballots; for status below ACCEPTED it records commands, updated attributes, ballot/value ballot and PREACCEPTED or PREACCEPTED_EQ.','Replies matching lastTriedBallot and a preaccepted bookkeeping status increment support and merge attributes; higher value ballots replace selected attributes/status.'],important_branches=['Fast decision requires FastQuorumSize()-1 replies, allEqual, committed-dependency condition for N>7, and initial ballot. Equality is skipped for N<=3 with thriftiness.','At the same threshold without fast precondition, coordinator installs ACCEPTED and broadcasts Accept.','For existing ACCEPTED-or-later state, PreAccept only fills missing commands; it indexes the command write by LeaderId, while reading the instance by Replica.'],external_effects=['Conditional metadata/command persistence and sync, PreAccept replies, Accept or Commit broadcasts, early client replies only if Dreply is false.'],produces_fact_ids=['F-record'],consumes_fact_ids=['F-record'],cross_activity_effects={'A2':'Ballot guards decide which requests/replies can affect formation.','A5':'A fast decision makes commands eligible for dependency execution.'})
