beh('B-context','A2','Recovery request or Prepare/PrepareReply dispatch',['M-recovery','M-ballot','M-default','M-commit'],writes=['Recovery retains pending client proposals, snapshots current value information into new bookkeeping, selects ballot and appends a self PrepareReply after overwriting local bal and vbal.','Prepare raises bal for a higher request, retaining vbal and value/status, then replies.','Matching prepare replies accumulate until SlowQuorumSize. Highest VBallot with last-on-tie selection supplies value/status. Recovery branches on COMMITTED, ACCEPTED, or preaccepted counts/equality/leader participation; otherwise restarts phase1, using NOOP for absent commands.'],important_branches=['Complete committed commands suppress recovery initiation. Selected committed state is installed without a Commit broadcast in this handler.','Old or mismatching prepare replies are rejected by preparing/ballot checks. New recovery bookkeeping resets old counters.','makeBallot uses replica identity, N, and only when IsLeader is true advances against maxRecvBallot. BeTheLeader sets IsLeader true; no revocation is shown.'],produces_fact_ids=['F-record'],consumes_fact_ids=['F-record'],cross_activity_effects={'A1':'Recovered status selects Accept versus renewed PreAccept, directly constraining subsequent decision formation.','A7':'Recovery carries existing client proposals into restarted phase1.'})
beh('B-commit','A1','Commit dispatch',['M-commit','M-attrs'],implementation_guards=['Ignore already committed/executed instances and commits below inst.bal.'],writes=['Install command, sequence, dependencies, bal/vbal and COMMITTED. Update conflict indexes and contiguous committed prefix.'],external_effects=['Record commands/metadata without local sync. A NOOP for the local row can requeue pending proposals.'],produces_fact_ids=['F-record'],consumes_fact_ids=['F-record'],cross_activity_effects={'A5':'Creates committed records consumed by execution.'})
beh('B-recover-trigger','A3','Execution scan encounters missing/uncommitted/commandless record',['M-dispatch'],execution_owner='executeCommands goroutine, then Replica.run',writes=['Track problematic instance and accumulated sleep quantum per row.'],external_effects=['After COMMIT_GRACE_PERIOD accounting, enqueue instance IDs through instancesToRecover for recovery; normal execution retries scanning.'],async_boundaries=['Execution reads shared instance records while handler loop updates them; full memory-synchronization analysis remains open.'],cross_activity_effects={'A2':'Queued recovery starts per-instance authority acquisition.'})
