beh('B-config','A4','Replica construction and peer connections',['M-replica','M-run','M-master','M-init'],execution_owner='Launcher, master and replica networking',protocol_context='Static registered node list and configured fault count',writes=['N derives from node list, F from configured address count. EPaxos construction forces Thrifty=true, LRead=false, Dreply defaults true; launcher disables durability.'],external_effects=['Master invokes BeTheLeader initially and after detected leader RPC failure. Peer Alive flags gate sends; listener failure marks a peer not alive.'],cross_activity_effects={'A1':'FastQuorumSize is F+(F+1)/2; SlowQuorumSize is (N+1)/2; Accept threshold uses N/2.','A2':'Master designation controls ballot retry behavior, not exclusive proposal admission.'})
